    combat: { damage:"magic", range:"melee", mobility:"high", burst:"very_high", dps:"high", durability:"medium", sustain:"medium", control:"knock_up_and_immobilize", engage:"high", disengage:"medium", waveClear:"high", objectiveDamage:"high" },
    mechanics: ["Пассивный эффект «Наследие кузнеца»: после применения двух разных навыков третий становится усиленным. Порядок двух первых навыков определяет, какой усиленный вариант появится третьим.","Усиленная коса создаёт опасную зону и замедляет; усиленные цепи дают контроль по области; усиленный меч наносит урон по траектории рывка и позволяет пережить часть ответного урона за счёт неуязвимости/нецелесообразности попадания по нему во время соответствующей фазы.","После применения усиленного навыка все три обычных навыка уходят на общий период перезарядки, а следующие базовые атаки усиливаются и притягивают задетых врагов. Это окно нужно учитывать до входа в бой.","Джулиан обычно играет лесником; актуальная база также отмечает альтернативную центральную линию, но основной профиль сборки здесь — лес и Retribution.","Ключевой выбор — не просто нажать доступный усиленный навык, а заранее решить, нужен ли урон, контроль или безопасный выход."],
    strengths: ["Три варианта усиленного навыка позволяют менять ответ под ситуацию.","Сильный взрывной урон и контроль после подготовки комбинации.","Может продолжать давление после первого усиленного навыка за счёт усиленных базовых атак и повторного цикла."],
    weaknesses: ["Ошибочный порядок навыков оставляет не тот инструмент для боя.","После усиленного навыка есть окно общей перезарядки, когда возможности ограничены.","Сильно зависит от уровня, фарма и поддержки команды при входе."],
    matchups: { strongAgainst: [], weakAgainst: [] },
    synergies: [],
    itemNotes: ["MLBBHub для Jungle Tempo в патче 2.2.23 показывает Arcane Boots, Feather of Heaven, Windtalker, Concentrated Energy, Holy Crystal и Divine Glaive; Mage Emblem и Retribution.","Сборка зависит от того, нужен ли ранний темп, устойчивость или магическое пробивание; не переносить автоматически на центральную линию."],
    teamfight: { preferredPlan:"Перед входом выбери усиленный эффект: меч для безопасного урона и выхода, цепи для остановки мобильной цели или косу для зоны и преследования. После усиления используй окно усиленных базовых атак и смещайся, пока навыки перезаряжаются. Лучше заходить после контроля союзника, а не открывать бой в одиночку.", targetPriority:["Уязвимая цель, на которой команда уже использовала часть защиты","Сгруппированные враги, если выбран усиленный контроль"], avoid:["Не трать усиленный навык до понимания, что именно требуется от комбинации.","Не врывайся первым без фронтлайна и последующего контроля.","Не пытайся продолжать размен в окно общей перезарядки, если противник может ответить."] },
    sources: ["https://www.mlbbguides.com/heroes/julian/passive-skill/","https://mlbbhub.com/heroes/julian","https://www.oneesports.gg/mobile-legends/julian-best-build-guide/","https://mlbbhub.com/heroes/julian","https://mlbb.io/en/hero/julian","https://mlbbdex.com/en/heroes/julian"],
