    combat: { damage:"physical", range:"melee", mobility:"very_high", burst:"high", dps:"medium", durability:"medium", sustain:"low", control:"knock_up_and_displacement", engage:"high", disengage:"high", waveClear:"medium", objectiveDamage:"low" },
    mechanics: ["Пассивный эффект «Только вперёд»: после перемещения на заданную дистанцию следующая базовая атака усиливается, замедляет и снижает физическую защиту цели. Это важная часть короткого размена и подготовки пик-оффа.","Первый навык «Джит Кун-До» выполняет серию из трёх рывков; третье применение подбрасывает врагов. Последний удар можно использовать для начала контроля перед ультимейтом.","Второй навык «Шунпо» даёт рывок и окно невосприимчивости к контролю, а также защитный эффект. Он нужен не только для входа, но и для выхода из опасной зоны.","Ультимейт «Путь дракона» сначала отбрасывает выбранного героя ударом, затем позволяет продолжить серию ударов. Направление первого удара решает, попадёт ли цель под союзный урон или будет спасена от команды.","Чу может играть на линии опыта или в роуме. Уронная сборка и танковый роум-вариант решают разные задачи и не должны смешиваться в одну рекомендацию."],
    strengths: ["Очень высокая мобильность и возможность выбирать угол атаки.","Может изолировать ключевую цель и переместить её относительно команды.","Второй навык помогает пережить часть контроля и выйти из опасной зоны."],
    weaknesses: ["Сложно реализовать ультимейт без понимания направления и позиции союзников.","Ошибочный удар может выбросить цель из командного урона.","В текущем рейтинговом срезе MLBBHub показывает низкую общую эффективность, поэтому это скорее ситуационный выбор, чем слепой пик."],
    matchups: { strongAgainst: [], weakAgainst: [] },
    synergies: [],
    itemNotes: ["MLBBHub для EXP Damage Dealer показывает Tough Boots, Blade of the Heptaseas, War Axe, Endless Battle, Malefic Roar и Immortality; Fighter Emblem и Flicker.","Для Roam нужна отдельная более защитная сборка и иной план инициации; не использовать уронный EXP-набор автоматически."],
    teamfight: { preferredPlan:"Ищи изолированную цель и заранее оцени, куда её отправит ультимейт. Используй второй навык для обхода контроля, а первый — для подбрасывания или продолжения преследования. Если играешь роумом, приоритет — безопасно вынести угрозу из боя, а не набрать личный урон.", targetPriority:["Стрелок или маг без готового очищения и рывка","Убийца, который уже вошёл в союзную заднюю линию"], avoid:["Не отправляй цель ультимейтом за пределы союзной досягаемости.","Не расходуй второй навык до ключевого вражеского контроля.","Не выбирай Чу вслепую против составов, которые легко прерывают его заход."] },
    sources: ["https://mlbb.io/en/hero/chou","https://mlbbhub.com/heroes/chou","https://www.oneesports.gg/mobile-legends/chou-best-build-guide/","https://mlbbhub.com/heroes/chou","https://mlbb.io/en/hero/chou","https://mlbbdex.com/en/heroes/chou"],
    patch: { version:HERO_DB_PATCH, notes:["Механики сверены по нескольким справочникам; числовые значения навыков не закреплены без отдельной проверки клиента.","Рейтинговые сборки и статистика отделены от профессиональной выборки; актуальный pro VOD review остаётся pending.","Матчапы и синергии оставлены пустыми, если нет достаточной сопоставимой выборки."], reviewedAt:"2026-11-22" },
